=Analyze the following lead and return the required CRM JSON.

Telegram User ID: {{ $json.body.message.from.id }}

Name: {{ $json.body.message.from.first_name || "Unknown" }} {{ $json.body.message.from.last_name || "" }}

Username: {{ $json.body.message.from.username || "Unknown" }}

Chat ID: {{ $json.body.message.chat.id }}

Customer Message:
{{ $json.body.message.text || "" }}

Analyze the customer's actual message carefully.

Return ONLY the JSON object required by the system instructions.

parameters.jsCode:
// ==========================================
// AI CRM Pipeline Manager
// Parse + Validate AI Lead Analyzer Output
// ==========================================

// Get AI node output
const input = $input.first().json;

// Get original Telegram webhook data
const webhook = $("Webhook").first().json;

// Telegram payload
const telegram = webhook.body || webhook;

const message = telegram.message || {};
const from = message.from || {};
const chat = message.chat || {};

// ==========================================
// 1. EXTRACT AI RESPONSE
// ==========================================

let aiContent =
  // n8n "Message a model" / Responses API structure
  input.output?.[0]?.content?.[0]?.text ??

  // Other possible OpenAI structures
  input.choices?.[0]?.message?.content ??
  input.message?.content ??
  input.content?.[0]?.text ??
  input.content ??
  input.text ??
  input.response;

// If nothing was found, throw an error instead
// of silently classifying the lead as Cold
if (!aiContent) {
  throw new Error(
    `Could not find AI response. Raw AI output: ${JSON.stringify(input)}`
  );
}

// ==========================================
// 2. PARSE AI JSON
// ==========================================

let parsed;

try {

  // In case OpenAI already returned an object
  if (typeof aiContent === "object") {
    parsed = aiContent;
  } else {

    const cleaned = String(aiContent)
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();

    parsed = JSON.parse(cleaned);
  }

} catch (error) {

  throw new Error(
    `AI response could not be parsed as JSON: ${aiContent}`
  );
}

// ==========================================
// 3. ALLOWED CRM VALUES
// ==========================================

const allowedLeadQualities = [
  "Hot",
  "Warm",
  "Cold"
];

const allowedPipelineStages = [
  "New Lead",
  "Qualified",
  "Contacted",
  "Interested",
  "Appointment Set",
  "Won",
  "Lost"
];

// ==========================================
// 4. VALIDATE AI OUTPUT
// ==========================================

let leadQuality = parsed.lead_quality;
let pipelineStage = parsed.pipeline_stage;

// Instead of silently accepting bad AI output,
// use safe CRM defaults
if (!allowedLeadQualities.includes(leadQuality)) {
  leadQuality = "Cold";
}

if (!allowedPipelineStages.includes(pipelineStage)) {
  pipelineStage = "New Lead";
}

// ==========================================
// 5. NORMALIZE requires_followup
// ==========================================

let requiresFollowup = parsed.requires_followup;

if (typeof requiresFollowup === "string") {
  requiresFollowup =
    requiresFollowup.toLowerCase() === "true";
}

if (typeof requiresFollowup !== "boolean") {
  requiresFollowup = false;
}

// ==========================================
// 6. MANILA TIMESTAMP
// ==========================================

const timestamp = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Manila",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false
})
.format(new Date())
.replace(", ", "T");

// ==========================================
// 7. BUILD CLEAN CRM RECORD
// ==========================================

const output = {

  timestamp,

  // Telegram identity
  telegram_user_id: from.id || "Unknown",
  chat_id: chat.id || "Unknown",

  first_name: from.first_name || "Unknown",
  last_name: from.last_name || "",
  username: from.username || "Unknown",

  // Customer message
  message: message.text || "",

  // AI CRM analysis
  lead_quality: leadQuality,
  pipeline_stage: pipelineStage,
  intent: parsed.intent || "Other",
  summary: parsed.summary || "No summary provided",
  next_action: parsed.next_action || "Review lead manually",
  requires_followup: requiresFollowup,

  // CRM status
  status:
    pipelineStage === "Won"
      ? "Won"
      : pipelineStage === "Lost"
      ? "Lost"
      : "Active"
};

// ==========================================
// 8. RETURN
// ==========================================

return [
  {
    json: output
  }
];

